// «Зууч» — Комплаенс: МУТСТ (харилцагчийг таньж мэдэх, хориг жагсаалт, СМА-ны тайлан) + СЗХ-ны зохицуулалт (зөвшөөрөл, ажилтан, мэдэгдэл, тайлангийн хуваарь)
// app.js-ийн $, esc, api, modal, closeModal, ME-г ашиглана.
(function () {
  let AM = null; let TAB = 'dash';
  if (!document.getElementById('aml-css')) { const st = document.createElement('style'); st.id = 'aml-css'; st.textContent = '@media (max-width:900px){.aml-grid{grid-template-columns:1fr!important}} @media print{aside,#aml-body button,.page-head .demo-note{display:none!important}}'; document.head.appendChild(st); }
  const RISK = { low: ['Бага', 'ok'], medium: ['Дунд', 'warn'], high: ['Өндөр', 'hi'] };
  const CDD = { simplified: 'Хялбаршуулсан', standard: 'Стандарт', enhanced: 'Нарийвчилсан' };
  const STAT = { draft: ['Бүрдүүлж буй', 'mut'], verified: ['Баталгаажсан', 'ok'], blocked: ['ХААСАН (хориг)', 'hi'] };
  const RT = { CTR: 'БМГТ — бэлэн мөнгөний гүйлгээ', STR: 'СГТ — сэжигтэй гүйлгээ', TFS: 'Хориг арга хэмжээ (царцаах)', RFI: 'СМА-ны хүсэлтэд хариу' };
  const POS = { executive: 'Гүйцэтгэх удирдлага', broker: 'Брокер', agent: 'Агент', sales: 'Борлуулалтын ажилтан', aml_officer: 'МУТСТ ажилтан', other: 'Бусад' };
  const b = (t, c) => `<span class="badge ${c === 'hi' ? '' : c}" ${c === 'hi' ? 'style="background:color-mix(in srgb,#dc2626 16%,transparent);color:#dc2626"' : ''}>${t}</span>`;
  const rb = (r) => b(...(RISK[r] || ['—', 'mut'])); const sb = (s) => (s === 'blocked' && AM && !AM.officer ? b('Түр зогсоосон — комплаенстай холбогдоно уу', 'warn') : b(...(STAT[s] || [s, 'mut']))); // хориг арга хэмжээг урьдчилан мэдэгдэлгүй авна (МУТСТХ 6¹.2)
  const tg = (n) => String(Math.round(Number(n || 0))).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  const dt = (v) => (v ? new Date(v).toLocaleString('sv-SE', { timeZone: 'Asia/Ulaanbaatar' }).slice(0, 16) : '');
  const d10 = (v) => (v ? String(v).slice(0, 10) : '');
  const cite = (c) => (c ? `<span style="font-size:11px;color:var(--muted)">· ${esc(c)}</span>` : '');
  const err = (r) => { if (r && r.error) { alert(r.error); return true; } return false; };
  const upload = async (url, fd) => (await fetch('/api' + url, { method: 'POST', headers: { Authorization: 'Bearer ' + TOKEN }, body: fd })).json();
  const pname = (p) => p.display || (p.kind === 'legal' ? (p.data || {}).name : [(p.data || {}).parent_name, (p.data || {}).given_name].filter(Boolean).join(' ')) || '—';

  window.compliance = async function (tab, arg) {
    if (tab) TAB = tab;
    AM = await api('/aml/overview'); if (AM.error) { $('#main').innerHTML = `<p>${esc(AM.error)}</p>`; return; }
    if (!AM.officer && !['mine', 'referral'].includes(TAB)) TAB = 'mine';
    const tabs = AM.officer
      ? [['dash', 'Хянах самбар'], ['profiles', 'Харилцагчийн ХТМ'], ['tx', 'Гүйлгээ'], ['reports', 'СМА-ны тайлан'], ['referrals', 'Сэжиг'], ['sanctions', 'Хориг жагсаалт'], ['staff', 'Ажилтан, гэрчилгээ'], ['program', 'Хөтөлбөр, сургалт'], ['frc', 'СЗХ'], ['audit', 'Аудит']]
      : [['mine', 'Миний ХТМ'], ['referral', 'Сэжиг мэдээлэх']];
    const cnt = AM.tasks ? AM.tasks.filter((t) => t.lvl === 'high' || t.overdue).length : 0;
    $('#main').innerHTML = `<div class="page-head"><h2><svg class=ic><use href=#i-shield-check></use></svg>Комплаенс <small style="font-size:13px;font-weight:500;color:var(--muted)">МУТСТ · СЗХ</small></h2>
      <span class="demo-note">${AM.encryption ? '🔒 Баримт AES-256 шифрлэлттэй' : '<b style="color:#dc2626">⚠ Баримтын шифрлэлт идэвхгүй (ZUUCH_DOC_KEY)</b>'}</span></div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${tabs.map(([k, t]) => `<button class="small ${TAB === k ? 'primary' : ''}" onclick="compliance('${k}')">${t}${k === 'dash' && cnt ? ` <b style="color:${TAB === k ? '#fff' : '#dc2626'}">${cnt}</b>` : ''}</button>`).join('')}</div>
      <div id="aml-body">Ачааллаж байна…</div>`;
    const R = { dash, profiles, tx, reports, referrals, sanctions, staff, program, frc, audit, mine: profiles, referral: referralForm }[TAB];
    if (arg && (TAB === 'profiles' || TAB === 'mine')) return profileView(arg);
    if (arg && TAB === 'reports') return reportView(arg);
    await R();
  };
  const body = (h) => { $('#aml-body').innerHTML = h; };

  // ---------------- Хянах самбар ----------------
  async function dash() {
    const s = AM.stats; const cntP = (f) => s.profiles.filter(f).reduce((a, x) => a + x.n, 0); const cntR = (t, st) => s.reports.filter((x) => x.type === t && x.status === st).reduce((a, x) => a + x.n, 0);
    const T = AM.tasks;
    body(`<div class="tiles">
      <div class="tile"><div class="v">${cntP((x) => x.status === 'verified')}<small style="font-size:13px"> / ${cntP(() => true)}</small></div><div class="k">Баталгаажсан ХТМ</div></div>
      <div class="tile"><div class="v" style="color:#dc2626">${cntP((x) => x.risk === 'high')}</div><div class="k">Өндөр эрсдэлтэй</div></div>
      <div class="tile"><div class="v">${s.pep}</div><div class="k">УТНБЭ</div></div>
      <div class="tile"><div class="v">${cntR('CTR', 'draft') + cntR('STR', 'draft') + cntR('TFS', 'draft')}</div><div class="k">Илгээгээгүй тайлан</div></div>
      <div class="tile"><div class="v">${s.txYear.n}</div><div class="k">Энэ оны гүйлгээ · ${tg(Number(s.txYear.total) / 1e6)} сая ₮</div></div></div>
    <div class="card"><h3>Хийх ажлууд, хугацаа</h3>${T.length ? `<div class="tablebox"><table><thead><tr><th style="width:90px">Ач холбогдол</th><th>Ажил</th><th style="width:150px">Хугацаа</th></tr></thead><tbody>${T.map((t) => `<tr style="cursor:${t.link ? 'pointer' : 'default'}" onclick='${t.link ? `amlGo(${JSON.stringify(t.link)})` : ''}'>
      <td>${t.overdue ? b('ХЭТЭРСЭН', 'hi') : t.lvl === 'high' ? b('Яаралтай', 'hi') : t.lvl === 'mid' ? b('Анхаарах', 'warn') : b('Төлөвлөх', 'mut')}</td><td>${esc(t.t)} ${cite(t.cite)}</td><td>${esc(t.due || '')}</td></tr>`).join('')}</tbody></table></div>` : '<div style="color:var(--ok)">✓ Хугацаа хэтэрсэн, яаралтай ажил алга.</div>'}</div>
    <div class="card" style="font-size:12.5px;color:var(--muted);line-height:1.6"><b style="color:var(--text)">Гол шаардлага:</b> ХТМ — бизнесийн харилцаа үүсгэхээс өмнө (МУТСТХ 5.1.1) · 20 сая ₮+ бэлэн мөнгө, гадаад төлбөр, виртуал хөрөнгийн гүйлгээ — СМА-д ажлын 5 өдөрт (7.1) · сэжигтэй гүйлгээ — 24 цагт (7.2), харилцагчид мэдэгдэхийг хориглоно (13.1) · хориг жагсаалтын тохирол — царцааж 24 цагт мэдээлэх (ҮОХЗДТТХ 23.6) · баримт — 5 жил (8.1) · СЗХ-ны улирлын тайлан — дараа улирлын эхний сарын 10 (№235) · өөрчлөлт мэдэгдэх — ажлын 10 өдөр (№648). Тайланг СМА-ны goAML порталаар илгээнэ — Зууч нь бэлтгэл, бүртгэл, хугацааны хяналтыг хийнэ.</div>`);
  }
  window.amlGo = (l) => compliance(l.tab, l.id || null);

  // ---------------- ХТМ профайл ----------------
  async function profiles() {
    const rows = await api('/aml/profiles'); const clients = await api('/clients').catch(() => []);
    body(`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px;align-items:center">
      <button class="primary small" onclick="amlNew('individual')">+ Иргэн</button><button class="small" onclick="amlNew('legal')">+ Хуулийн этгээд</button>
      <input id="aml-q" placeholder="Нэр, регистр…" style="width:200px" oninput="amlFilter()"> <span style="font-size:12px;color:var(--muted)">Бизнесийн харилцаа үүсгэхээс (гэрээ, урьдчилгаа) өмнө бөглөнө — МУТСТХ 5.1.1</span></div>
    <div class="tablebox"><table id="aml-pt"><thead><tr><th>Нэр</th><th>Төрөл</th><th>CRM харилцагч</th><th>Эрсдэл</th><th>ХТМ</th><th>Төлөв</th><th>Дахин шалгах</th>${AM.officer ? '<th>Бүртгэсэн</th>' : ''}</tr></thead><tbody>
    ${rows.map((p) => `<tr style="cursor:pointer" data-q="${esc(JSON.stringify([pname(p), p.data.register_no, p.data.state_reg_no, p.client_name]).toLowerCase())}" onclick="compliance('${AM.officer ? 'profiles' : 'mine'}', ${p.id})">
      <td><b>${esc(pname(p))}</b>${p.pep && p.pep.is ? ' ' + b('УТНБЭ', 'warn') : ''}${p.sanctions && (p.sanctions.pending || (p.sanctions.hits || []).some((h) => !h.cleared)) ? ' ' + (AM.officer ? b('Хориг: шалгах', 'hi') : b('Комплаенс шалгаж байна', 'mut')) : ''}</td>
      <td>${p.kind === 'legal' ? 'Хуулийн этгээд' : 'Иргэн'}</td><td>${esc(p.client_name || '')}</td><td>${rb(p.risk)}</td><td>${CDD[p.cdd] || ''}</td><td>${sb(p.status)}${p.ended_at ? ' ' + b('Дууссан', 'mut') : ''}</td><td>${d10(p.review_due)}</td>${AM.officer ? `<td>${esc(p.created_by_name || '')}</td>` : ''}</tr>`).join('') || '<tr><td colspan="8" style="color:var(--muted)">Бүртгэл алга</td></tr>'}</tbody></table></div>`);
    window._amlClients = clients;
  }
  window.amlOpen = (id) => profileView(id);
  window.amlFilter = () => { const q = $('#aml-q').value.toLowerCase(); document.querySelectorAll('#aml-pt tbody tr[data-q]').forEach((tr) => { tr.style.display = tr.dataset.q.includes(q) ? '' : 'none'; }); };
  window.amlNew = (kind) => profileView(null, kind);

  const F = (label, name, val, opt = {}) => `<div class="field ${opt.wide ? 'wide' : ''}"><label>${label}${opt.req ? ' <b style="color:#dc2626">*</b>' : ''}</label>${opt.sel ? `<select name="${name}">${opt.sel.map(([v, t]) => `<option value="${esc(v)}" ${String(val ?? '') === String(v) ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select>` : opt.area ? `<textarea name="${name}" rows="${opt.rows || 2}">${esc(val || '')}</textarea>` : `<input name="${name}" type="${opt.type || 'text'}" value="${esc(val || '')}" ${opt.ph ? `placeholder="${esc(opt.ph)}"` : ''}>`}</div>`;
  const CH = [['in_person', 'Биечлэн уулзсан'], ['remote', 'Зайнаас (онлайн, утсаар)'], ['third_party', 'Гуравдагч этгээдээр дамжуулж']];

  async function profileView(id, kind) {
    const p = id ? await api('/aml/profiles/' + id) : { kind, data: {}, bo: [], pep: {}, factors: {}, docs: [], gaps: [], sanctions: {} };
    if (p.error) return body(`<p>${esc(p.error)}</p>`);
    const d = p.data || {}; const L = p.kind === 'legal'; const clients = window._amlClients || await api('/clients').catch(() => []);
    const R = AM.rules; const isZ = ME.role === 'zahiral' || ME.is_owner;
    const hits = (p.sanctions && p.sanctions.hits) || [];
    body(`<div style="display:flex;gap:8px;align-items:center;margin-bottom:10px;flex-wrap:wrap"><button class="small" onclick="compliance('${AM.officer ? 'profiles' : 'mine'}')">← Жагсаалт</button>
      <h3 style="margin:0">${id ? esc(pname(p)) : L ? 'Шинэ хуулийн этгээд' : 'Шинэ иргэн'}</h3>${id ? `${rb(p.risk)} ${sb(p.status)} <span style="font-size:12.5px">${CDD[p.cdd] || ''} ХТМ</span>` : ''}</div>
    <div style="display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:14px;align-items:start" class="aml-grid">
    <form id="aml-f">
      <div class="card"><h3>${L ? 'Хуулийн этгээд' : 'Иргэн'} <span style="font-size:12px;color:var(--muted);font-weight:400">${L ? 'МУТСТХ 5.2.2–5.2.5; УСҮАЖ 3.3' : 'МУТСТХ 5.2.1; УСҮАЖ 3.2'}</span></h3><div class="form-grid" style="grid-template-columns:1fr 1fr">
      ${F('CRM харилцагч (холбох)', 'client_id', p.client_id, { sel: [['', '—'], ...clients.map((c) => [c.id, c.name + (c.phone ? ' · ' + c.phone : '')])] })}
      ${L ? F('Нэр', 'name', d.name, { req: 1 }) + F('Нэр (латин)', 'name_latin', d.name_latin) + F('Улсын бүртгэлийн дугаар', 'state_reg_no', d.state_reg_no, { req: 1 }) + F('Татвар төлөгчийн дугаар', 'tax_no', d.tax_no, { req: 1 }) + F('Үйл ажиллагааны чиглэл', 'activity', d.activity) + F('Улс (ISO 2 үсэг)', 'country', d.country || 'MN', { ph: 'MN' }) + F('Хаяг', 'address', d.address, { req: 1, wide: 1 }) + F('Утас', 'phone', d.phone, { req: 1 }) + F('И-мэйл', 'email', d.email) + F('Удирдлага (гүйцэтгэх захирал, ТУЗ)', 'management', d.management, { req: 1, area: 1, wide: 1 }) + F('Төлөөлөгчийн нэр', 'rep_name', d.rep_name, { req: 1 }) + F('Албан тушаал', 'rep_position', d.rep_position) + F('Төлөөлөх эрхийн баримт (итгэмжлэл №, огноо)', 'rep_authority', d.rep_authority, { req: 1, wide: 1 }) + F('Өмчлөлийн бүтцийн тайлбар', 'ownership_note', d.ownership_note, { area: 1, wide: 1 })
    : F('Ургийн овог', 'surname', d.surname, { req: 1 }) + F('Эцэг/эхийн нэр', 'parent_name', d.parent_name, { req: 1 }) + F('Өөрийн нэр', 'given_name', d.given_name, { req: 1 }) + F('Нэр (латин, паспортоор)', 'name_latin', d.name_latin) + F('Төрсөн огноо', 'birth_date', d.birth_date, { type: 'date', req: 1 }) + F('Регистрийн дугаар', 'register_no', d.register_no, { req: 1 }) + F('Баримт', 'id_doc_type', d.id_doc_type || 'id', { sel: [['id', 'Иргэний үнэмлэх'], ['passport', 'Паспорт'], ['foreign_id', 'Гадаад иргэний үнэмлэх']] }) + F('Баримтын дугаар', 'id_doc_no', d.id_doc_no, { req: 1 }) + F('Иргэншил (ISO)', 'citizenship', d.citizenship || 'MN') + F('Оршин суугаа улс (ISO)', 'country', d.country || 'MN') + F('Байнгын хаяг', 'address', d.address, { req: 1, wide: 1 }) + F('Одоогийн хаяг (өөр бол)', 'address_current', d.address_current, { wide: 1 }) + F('Утас', 'phone', d.phone, { req: 1 }) + F('И-мэйл', 'email', d.email) + F('Эрхэлж буй ажил, бизнес', 'occupation', d.occupation, { req: 1 }) + F('Ажлын газар, албан тушаал', 'employer', d.employer) + F('Орлогын эх үүсвэр', 'income_source', d.income_source, { wide: 1 })}
      ${F('Харилцааны зорилго, гүйлгээний утга', 'purpose', d.purpose, { req: 1, wide: 1, ph: 'Жишээ: Хан-Уул дүүрэгт 2 өрөө орон сууц худалдан авах' })}
      ${F('ХТМ хийсэн суваг', 'channel', d.channel || 'in_person', { sel: CH })}
      <div class="field"><label>&nbsp;</label><label style="display:flex;gap:6px;align-items:center;font-weight:400"><input type="checkbox" name="acting_for" ${d.acting_for ? 'checked' : ''} style="width:auto"> Өөр этгээдийг төлөөлж байна</label></div>
      ${F('Төлөөлүүлэгчийн нэр, регистр', 'acting_for_name', d.acting_for_name, { wide: 1 })}
      ${F('Хөрөнгийн эх үүсвэр (худалдан авах мөнгө хаанаас)', 'source_of_funds', d.source_of_funds, { area: 1, wide: 1 })}
      ${F('Тэмдэглэл', 'note', d.note, { area: 1, wide: 1 })}</div></div>
      ${L ? `<div class="card"><h3>Эцсийн өмчлөгч <span style="font-size:12px;color:var(--muted);font-weight:400">${R.bo_percent}%+ шууд/шууд бус эзэмшил эсвэл хяналт · УСҮАЖ 4.3; гэр бүлийн эзэмшлийг нэгтгэнэ (4.5.2)</span></h3>
        <div class="tablebox"><table id="aml-bo"><thead><tr><th>Овог нэр</th><th>Регистр</th><th>Төрсөн огноо</th><th>Улс</th><th>%</th><th>Хяналт</th><th>УТНБЭ</th><th></th></tr></thead><tbody>${(p.bo || []).map(boRow).join('')}</tbody></table></div><button type="button" class="small" style="margin-top:6px" onclick="amlBoAdd()">+ Эцсийн өмчлөгч</button></div>` : ''}
      <div class="card"><h3>Улс төрд нөлөө бүхий этгээд (УТНБЭ) <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 3.1.5, АСЗХ 20.2 — одоо болон өмнө эрхэлж байсан</span></h3>
        <label style="display:flex;gap:6px;align-items:center"><input type="checkbox" name="pep_is" ${p.pep && p.pep.is ? 'checked' : ''} style="width:auto"> Харилцагч (эсвэл гэр бүлийн гишүүн, ойр дотны этгээд) нь УТНБЭ</label>
        <div class="form-grid" style="grid-template-columns:1fr 1fr;margin-top:8px">
        ${F('Албан тушаал', 'pep_position', (p.pep || {}).position, { sel: [['', '—'], ...R.pep_positions.map((x) => [x, x])] })}${F('Хамаарал', 'pep_relation', (p.pep || {}).relation || 'self', { sel: Object.entries(R.pep_relations) })}
        ${F('УТНБЭ-ийн овог нэр (өөрөө биш бол)', 'pep_name', (p.pep || {}).pep_name)}${F('Хөрөнгийн эх үүсвэр (УТНБЭ)', 'pep_sof', (p.pep || {}).source_of_funds, { area: 1, wide: 1 })}</div></div>
      <div class="card"><h3>Эрсдэлийн хүчин зүйл <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 4.3 — харилцагч, бүтээгдэхүүн, суваг, газарзүй</span></h3>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:4px 14px;font-size:13px">${R.factors.map((x) => `<label style="display:flex;gap:6px;align-items:flex-start;font-weight:400"><input type="checkbox" name="f_${x.k}" ${p.factors && p.factors[x.k] ? 'checked' : ''} style="width:auto;margin-top:3px"> ${esc(x.t)}</label>`).join('')}
        <label style="display:flex;gap:6px;align-items:flex-start;font-weight:400"><input type="checkbox" name="f_suspicion" ${p.factors && p.factors.suspicion ? 'checked' : ''} style="width:auto;margin-top:3px"> Сэжиг төрсөн (хялбаршуулсан ХТМ хориглоно)</label></div>
        <div style="font-size:12px;color:var(--muted);margin-top:6px">УТНБЭ, ФАТФ-ын хар жагсаалтын улс, зайнаас/гуравдагч этгээдээр хийсэн ХТМ, хориг жагсаалтын тохирол → автоматаар <b>өндөр</b> эрсдэл, нарийвчилсан ХТМ (МУТСТХ 5.3, 5.9; УСҮАЖ 7.2).</div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px"><button class="primary">Хадгалах (хориг жагсаалтаар шалгана)</button>${id ? `<button type="button" class="small" onclick="amlReferral(${id})">Сэжиг мэдээлэх</button>` : ''}</div>
    </form>
    <div>${id ? `<div class="card"><h3>Үнэлгээ</h3><div style="font-size:13px;line-height:1.7">Эрсдэл: ${rb(p.risk)}${p.risk_score ? ` (оноо ${p.risk_score})` : ''}<br>ХТМ: <b>${CDD[p.cdd] || ''}</b><br>Төлөв: ${sb(p.status)}${p.verified_at ? `<br><span style="font-size:12px;color:var(--muted)">Баталгаажсан: ${dt(p.verified_at)}</span>` : ''}${p.edd_approved_at ? `<br><span style="font-size:12px;color:var(--muted)">Удирдлагын зөвшөөрөл: ${dt(p.edd_approved_at)}</span>` : ''}<br>Дахин шалгах: ${d10(p.review_due)}</div>
        ${(p.risk_reasons || []).length ? `<ul style="font-size:12.5px;padding-left:18px;margin:8px 0 0">${p.risk_reasons.map((r) => `<li>${esc(r.t)}${r.w ? ` (+${r.w})` : ''}</li>`).join('')}</ul>` : ''}
        ${p.gaps && p.gaps.length ? `<div style="margin-top:10px;font-size:12.5px"><b style="color:#b45309">Дутуу (${p.gaps.length}):</b><ul style="padding-left:18px;margin:4px 0">${p.gaps.map((g) => `<li>${esc(g)}</li>`).join('')}</ul></div>` : p.status !== 'verified' ? '<div style="margin-top:8px;color:var(--ok);font-size:12.5px">✓ Бүрдэл бүрэн — эх хувьтай тулгаад баталгаажуулна уу</div>' : ''}
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">${p.status !== 'verified' && p.status !== 'blocked' ? `<button class="small primary" onclick="amlVerify(${id})">Баталгаажуулах</button>` : ''}${p.cdd === 'enhanced' && !p.edd_approved_at && isZ ? `<button class="small" onclick="amlApprove(${id})">Удирдлагын зөвшөөрөл өгөх</button>` : ''}${AM.officer && !p.ended_at ? `<button class="small" onclick="amlEnd(${id})">Харилцаа дууссан</button>` : ''}</div></div>
      <div class="card"><h3>Баримт <span style="font-size:12px;color:var(--muted);font-weight:400">${AM.encryption ? '🔒 шифрлэгдэнэ' : ''}</span></h3>
        ${(p.docs || []).map((x) => `<div style="font-size:12.5px;padding:4px 0;border-bottom:1px solid var(--line)"><a href="#" onclick="amlDoc(${x.id});return false">${esc(R.doc_kinds[x.kind] || x.kind)}</a> <span style="color:var(--muted)">${Math.max(1, Math.round(x.size / 1024))} KB · ${dt(x.created_at)}</span> ${x.original_seen ? b('эх хувьтай тулгасан', 'ok') : `<button class="small" onclick="amlSeen(${x.id},${id})">Эх хувьтай тулгасан</button>`}</div>`).join('') || '<div style="font-size:12.5px;color:var(--muted)">Баримт алга</div>'}
        <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap"><select id="aml-dk" style="width:auto">${(L ? ['cert', 'poa', 'bo', 'sof', 'contract', 'other'] : ['id', 'poa', 'sof', 'contract', 'other']).map((k) => `<option value="${k}">${esc(R.doc_kinds[k])}</option>`).join('')}</select><input type="file" id="aml-df" accept="application/pdf,image/*" style="width:100%;min-width:0"><button class="small" onclick="amlDocUp(${id})">Оруулах</button></div>
        <div style="font-size:11.5px;color:var(--muted);margin-top:6px">Хуулбарыг эх хувьтай нь тулгаж тэмдэглэнэ (МУТСТХ 5.2.1). Баримтыг харилцаа дууссанаас хойш 5 жил хадгална (8.1).</div></div>
      <div class="card"><h3>Хориг жагсаалт</h3><div style="font-size:12.5px;color:var(--muted)">Шалгасан: ${dt(p.sanctions && p.sanctions.checked_at) || '—'}${p.sanctions && p.sanctions.lists ? ` · НҮБ ${p.sanctions.lists.un || 0}, дотоод ${p.sanctions.lists.mn || 0}` : ''}</div>
        ${AM.officer ? (hits.length ? hits.map((h, i) => `<div style="border:1px solid var(--line);border-radius:6px;padding:8px;margin-top:6px;font-size:12.5px"><b>${esc(h.name)}</b> · ${esc(h.source)} ${esc(h.ref)} · тохирол ${Math.round(h.score * 100)}%${h.dob === true ? ' · төрсөн огноо таарсан' : h.dob === false ? ' · төрсөн огноо зөрсөн' : ''} · ${esc(h.who)}<br>${h.cleared ? b('Худал тохирол', 'ok') + ` ${esc(h.note || '')}` : h.confirmed ? b('БАТАЛГААЖСАН — хаасан', 'hi') : `<button class="small" onclick="amlHit(${id},${i},'clear')">Худал тохирол</button> <button class="small" style="color:#dc2626" onclick="amlHit(${id},${i},'confirm')">Баталгаажуулах (царцаах)</button>`}</div>`).join('') : '<div style="color:var(--ok);font-size:12.5px;margin-top:6px">✓ Тохирол илрээгүй</div>') : (p.sanctions && p.sanctions.pending ? '<div style="font-size:12.5px;margin-top:6px">Комплаенсын ажилтан шалгаж байна.</div>' : '<div style="color:var(--ok);font-size:12.5px;margin-top:6px">✓ Шалгагдсан</div>')}</div>` : '<div class="card" style="font-size:12.5px;color:var(--muted)">Хадгалсны дараа эрсдэл тооцогдож, хориг жагсаалтаар шалгагдаж, баримт оруулах боломжтой болно.</div>'}</div></div>`);
    $('#aml-f').addEventListener('submit', async (e) => {
      e.preventDefault(); const f = e.target; const fd = new FormData(f); const data = {};
      for (const [k, v] of fd.entries()) if (!/^(client_id|pep_|f_|bo_)/.test(k)) data[k] = v;
      data.acting_for = f.acting_for.checked;
      const factors = {}; for (const el of f.querySelectorAll('input[name^="f_"]')) if (el.checked) factors[el.name.slice(2)] = true;
      const pep = { is: f.pep_is.checked, position: f.pep_position.value, relation: f.pep_relation.value, pep_name: f.pep_name.value, source_of_funds: f.pep_sof.value };
      const bo = [...document.querySelectorAll('#aml-bo tbody tr')].map((tr) => ({ name: tr.querySelector('[data-k=name]').value, register_no: tr.querySelector('[data-k=register_no]').value, birth_date: tr.querySelector('[data-k=birth_date]').value, country: tr.querySelector('[data-k=country]').value, pct: tr.querySelector('[data-k=pct]').value, control: tr.querySelector('[data-k=control]').checked, pep: tr.querySelector('[data-k=pep]').checked }));
      const payload = { kind: p.kind, client_id: f.client_id.value || null, data, pep, factors, ...(L ? { bo } : {}) };
      const r = await api('/aml/profiles' + (id ? '/' + id : ''), { method: id ? 'PUT' : 'POST', body: payload }); if (err(r)) return;
      if (r.sanctions && ((r.sanctions.hits || []).some((h) => !h.cleared && !h.confirmed) || r.sanctions.pending)) alert('Хориг жагсаалтын боломжит тохирол илэрлээ. Комплаенсын ажилтан шийдвэрлэх хүртэл гэрээ, төлбөр хүлээн авахгүй байна уу.');
      profileView(r.id);
    });
  }
  const boRow = (x = {}) => `<tr><td><input data-k="name" value="${esc(x.name || '')}"></td><td><input data-k="register_no" value="${esc(x.register_no || '')}" style="width:110px"></td><td><input data-k="birth_date" type="date" value="${esc(x.birth_date || '')}"></td><td><input data-k="country" value="${esc(x.country || 'MN')}" style="width:50px"></td><td><input data-k="pct" type="number" min="0" max="100" value="${esc(x.pct ?? '')}" style="width:64px"></td><td><input data-k="control" type="checkbox" ${x.control ? 'checked' : ''} style="width:auto"></td><td><input data-k="pep" type="checkbox" ${x.pep ? 'checked' : ''} style="width:auto"></td><td><button type="button" class="small" onclick="this.closest('tr').remove()">✕</button></td></tr>`;
  window.amlBoAdd = () => $('#aml-bo tbody').insertAdjacentHTML('beforeend', boRow());
  window.amlVerify = async (id) => { if (!confirm('Баримтуудыг эх хувьтай нь тулгаж, мэдээлэл үнэн зөв болохыг баталгаажуулж байна уу?')) return; const r = await api(`/aml/profiles/${id}/verify`, { method: 'POST' }); if (!err(r)) profileView(id); };
  window.amlApprove = async (id) => { const note = prompt('Гүйцэтгэх удирдлагын зөвшөөрлийн тайлбар (УСҮАЖ 7.5.2):', 'Хөрөнгийн эх үүсвэрийг нягталсан'); if (note === null) return; const r = await api(`/aml/profiles/${id}/approve`, { method: 'POST', body: { note } }); if (!err(r)) profileView(id); };
  window.amlEnd = async (id) => { const d = prompt('Харилцаа дууссан огноо (5 жилийн хадгалалт эндээс тоологдоно):', new Date().toISOString().slice(0, 10)); if (!d) return; const r = await api(`/aml/profiles/${id}/end`, { method: 'POST', body: { date: d } }); if (!err(r)) { alert('Хадгалах хугацаа: ' + r.retain_until + ' хүртэл'); profileView(id); } };
  window.amlHit = async (id, i, decision) => { const note = prompt(decision === 'clear' ? 'Худал тохирол гэж үзсэн үндэслэл (төрсөн огноо, иргэншил, баримт):' : 'Баталгаажуулсан үндэслэл. Хөрөнгийг царцааж, тагнуулын байгууллага болон СМА-д 24 цагийн дотор мэдээлэх ажил үүснэ:'); if (!note) return; const r = await api(`/aml/profiles/${id}/hits/${i}`, { method: 'POST', body: { decision, note } }); if (!err(r)) profileView(id); };
  window.amlDocUp = async (id) => { const f = $('#aml-df').files[0]; if (!f) return alert('Файл сонгоно уу'); const fd = new FormData(); fd.append('file', f); fd.append('kind', $('#aml-dk').value); const r = await upload(`/aml/profiles/${id}/docs`, fd); if (!err(r)) profileView(id); };
  window.amlSeen = async (docId, id) => { const r = await api(`/aml/docs/${docId}/seen`, { method: 'POST' }); if (!err(r)) profileView(id); };
  window.amlDoc = async (docId) => { const r = await fetch('/api/aml/docs/' + docId, { headers: { Authorization: 'Bearer ' + TOKEN } }); if (!r.ok) return alert((await r.json()).error); const u = URL.createObjectURL(await r.blob()); window.open(u, '_blank', 'noopener'); setTimeout(() => URL.revokeObjectURL(u), 60000); };
  window.amlReferral = (pid) => referralForm(pid);

  // ---------------- Гүйлгээ ----------------
  async function tx() {
    const rows = await api('/aml/tx');
    body(`<div style="display:flex;gap:8px;margin-bottom:10px;align-items:center;flex-wrap:wrap"><button class="primary small" onclick="amlTx()">+ Гүйлгээ</button><span style="font-size:12px;color:var(--muted)">«Хэлцэл» хэсэгт худалдах хэлцэл бүртгэхэд энд автоматаар орно. 20 сая ₮+ бэлэн/гадаад/виртуал/чек → БМГТ автоматаар (МУТСТХ 7.1). Түрээс хамаарахгүй (4.1.7).</span></div>
    <div class="tablebox"><table><thead><tr><th>Огноо</th><th>Объект</th><th class="num">Дүн ₮</th><th>Хэлбэр</th><th>Худалдан авагч</th><th>Худалдагч</th><th>Тайлан</th><th></th></tr></thead><tbody>${rows.map((t) => `<tr>
      <td>${d10(t.tx_date)}</td><td>${esc([t.district, t.khoroolol].filter(Boolean).join(', '))}${t.deal_id ? ` <span style="color:var(--muted);font-size:11px">хэлцэл #${t.deal_id}</span>` : ''}</td><td class="num">${tg(t.amount)}</td><td>${esc((AM.rules.methods[t.method] || {}).t || t.method)}${t.third_party ? ' ' + b('3-р этгээд', 'warn') : ''}</td>
      <td>${t.buyer_id ? `<a href="#" onclick="compliance('profiles',${t.buyer_id});return false">${esc(t.b_name || t.b_given || '#' + t.buyer_id)}</a> ${sb(t.b_status)}` : b('ХТМ алга', 'hi')}</td>
      <td>${t.seller_id ? `<a href="#" onclick="compliance('profiles',${t.seller_id});return false">${esc(t.s_name || t.s_given || '#' + t.seller_id)}</a> ${sb(t.s_status)}` : b('ХТМ алга', 'hi')}</td>
      <td>${(t.reports || []).map((r) => `<a href="#" onclick="compliance('reports',${r.id});return false">${r.type}</a> ${r.status === 'submitted' ? b('илгээсэн', 'ok') : b('илгээгээгүй', 'hi')}`).join(' ')}</td><td><button class="small" onclick='amlTx(${JSON.stringify(t).replace(/'/g, '&#39;')})'>Засах</button></td></tr>`).join('') || '<tr><td colspan="8" style="color:var(--muted)">Гүйлгээ алга</td></tr>'}</tbody></table></div>`);
  }
  window.amlTx = async (t = {}) => {
    const ps = await api('/aml/profiles'); const opt = (sel) => `<option value="">—</option>` + ps.map((p) => `<option value="${p.id}" ${sel == p.id ? 'selected' : ''}>${esc(pname(p))} (${p.kind === 'legal' ? 'ХЭ' : 'иргэн'})</option>`).join('');
    modal(`<h3>${t.id ? 'Гүйлгээ засах' : 'Шинэ гүйлгээ'}</h3><form id="f" class="form-grid">
      <div class="field"><label>Дүн (₮)</label><input name="amount" type="number" min="1" value="${t.amount || ''}" required></div>
      <div class="field"><label>Төлбөрийн хэлбэр</label><select name="method">${Object.entries(AM.rules.methods).map(([k, m]) => `<option value="${k}" ${t.method === k ? 'selected' : ''}>${esc(m.t)}</option>`).join('')}</select></div>
      <div class="field"><label>Огноо</label><input name="tx_date" type="date" value="${d10(t.tx_date) || new Date().toISOString().slice(0, 10)}" required></div>
      <div class="field"><label>Хэлцэл №</label><input name="deal_id" type="number" value="${t.deal_id || ''}"></div>
      <div class="field"><label>Худалдан авагч (ХТМ)</label><select name="buyer_id">${opt(t.buyer_id)}</select></div>
      <div class="field"><label>Худалдагч (ХТМ)</label><select name="seller_id">${opt(t.seller_id)}</select></div>
      <div class="field wide"><label>Утга</label><input name="purpose" value="${esc(t.purpose || 'Үл хөдлөх хөрөнгө худалдах, худалдан авах')}"></div>
      <div class="field wide"><label style="display:flex;gap:6px;align-items:center"><input type="checkbox" name="third_party" ${t.third_party ? 'checked' : ''} style="width:auto"> Төлбөрийг гуравдагч этгээд төлсөн</label></div>
      <div class="field wide"><label>Тэмдэглэл</label><textarea name="note" rows="2">${esc(t.note || '')}</textarea></div>
      <div class="modal-actions wide"><button type="button" onclick="closeModal()">Болих</button><button class="primary">Хадгалах</button></div></form>`);
    $('#f').addEventListener('submit', async (e) => { e.preventDefault(); const o = Object.fromEntries(new FormData(e.target)); o.third_party = e.target.third_party.checked; const r = await api('/aml/tx' + (t.id ? '/' + t.id : ''), { method: t.id ? 'PUT' : 'POST', body: o }); if (err(r)) return; closeModal(); compliance('tx'); });
  };

  // ---------------- СМА-ны тайлан ----------------
  async function reports() {
    const rows = await api('/aml/reports');
    body(`<div style="display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap;align-items:center"><button class="primary small" onclick="amlNewReport('STR')">+ Сэжигтэй гүйлгээний тайлан</button><button class="small" onclick="amlNewReport('RFI')">+ СМА-ны хүсэлтэд хариу</button>
      <span style="font-size:12px;color:var(--muted)">Тайланг СМА-ны <b>goAML</b> порталаар илгээгээд бүртгэлийн дугаарыг энд тэмдэглэнэ (А-171). Тайлангийн талаар харилцагчид мэдэгдэхийг хориглоно (МУТСТХ 13.1).</span></div>
    <div class="tablebox"><table><thead><tr><th>№</th><th>Төрөл</th><th>Үндэслэл</th><th>Илэрсэн</th><th>Эцсийн хугацаа</th><th>Төлөв</th></tr></thead><tbody>${rows.map((r) => {
      const late = r.status === 'draft' && r.due_at && new Date(r.due_at) < new Date();
      return `<tr style="cursor:pointer" onclick="compliance('reports',${r.id})"><td>${r.id}</td><td>${esc(RT[r.type])}</td><td>${esc((r.grounds || '').slice(0, 90))}</td><td>${dt(r.detected_at)}</td><td>${r.due_at ? (late ? b(dt(r.due_at) + ' ХЭТЭРСЭН', 'hi') : dt(r.due_at)) : ''}</td><td>${r.status === 'submitted' ? b('Илгээсэн · ' + esc(r.goaml_ref || ''), 'ok') : b('Илгээгээгүй', 'warn')}</td></tr>`;
    }).join('') || '<tr><td colspan="6" style="color:var(--muted)">Тайлан алга</td></tr>'}</tbody></table></div>`);
  }
  window.amlNewReport = async (type) => { const r = await api('/aml/reports', { method: 'POST', body: { type, grounds: '' } }); if (!err(r)) compliance('reports', r.id); };
  async function reportView(id) {
    const r = await api('/aml/reports/' + id); if (err(r)) return; const f = r.form; const ps = await api('/aml/profiles'); const sub = r.status === 'submitted';
    const kv = (o) => (o ? Object.entries(o).filter(([, v]) => v !== '' && v != null && !(Array.isArray(v) && !v.length) && typeof v !== 'object').map(([k, v]) => `<tr><td style="color:var(--muted);width:40%">${esc(k)}</td><td>${esc(v)}</td></tr>`).join('') : '');
    body(`<div style="display:flex;gap:8px;align-items:center;margin-bottom:10px;flex-wrap:wrap"><button class="small" onclick="compliance('reports')">← Тайлангууд</button><h3 style="margin:0">${esc(RT[r.type])} №${r.id}</h3>${sub ? b('Илгээсэн ' + dt(r.submitted_at) + ' · goAML ' + esc(r.goaml_ref), 'ok') : b('Эцсийн хугацаа ' + dt(r.due_at), 'warn')}<button class="small" onclick="window.print()">Хэвлэх</button></div>
    <div class="card"><h3>Тайлангийн агуулга <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 9.1 — goAML-д оруулах мэдээлэл</span></h3>
      <form id="rf"><div class="form-grid"><div class="field"><label>Холбогдох харилцагч (ХТМ)</label><select name="profile_id" ${sub ? 'disabled' : ''}><option value="">—</option>${ps.map((p) => `<option value="${p.id}" ${r.profile_id == p.id ? 'selected' : ''}>${esc(pname(p))}</option>`).join('')}</select></div>
      <div class="field"><label>Илэрсэн / мэдсэн огноо, цаг</label><input name="detected_at" type="datetime-local" value="${r.detected_at ? new Date(new Date(r.detected_at).getTime() + 8 * 3600e3).toISOString().slice(0, 16) : ''}" disabled></div>
      <div class="field wide"><label>Сэжиглэх үндэслэл, нөхцөл байдлын тайлбар</label><textarea name="grounds" rows="5" ${sub ? 'disabled' : ''}>${esc(r.grounds || '')}</textarea></div>
      ${r.type === 'STR' ? `<div class="field wide"><label>Шинж тэмдэг (ФАТФ-ын үл хөдлөх хөрөнгийн салбарын удирдамж, 2022)</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 12px;font-size:12.5px">${AM.rules.indicators.map((x) => `<label style="display:flex;gap:6px;font-weight:400"><input type="checkbox" name="ind" value="${esc(x)}" ${(r.indicators || []).includes(x) ? 'checked' : ''} ${sub ? 'disabled' : ''} style="width:auto"> ${esc(x)}</label>`).join('')}</div></div>` : ''}
      </div>${sub ? '' : '<button class="primary small">Хадгалах</button>'}</form></div>
    <div class="card"><h3>Мэдээлэгч</h3><table style="font-size:12.5px">${kv(f.reporter)}</table></div>
    ${f.customer ? `<div class="card"><h3>Харилцагч</h3><table style="font-size:12.5px">${kv(f.customer)}</table>${(f.customer.bo || []).length ? `<div style="font-size:12.5px;margin-top:6px"><b>Эцсийн өмчлөгч:</b> ${f.customer.bo.map((x) => esc(`${x.name} ${x.pct}%`)).join(', ')}</div>` : ''}</div>` : ''}
    ${f.transaction ? `<div class="card"><h3>Гүйлгээ</h3><table style="font-size:12.5px">${kv(f.transaction)}</table></div>` : ''}
    ${sub ? '' : `<div class="card"><h3>goAML-аар илгээсэн</h3><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end"><label>goAML бүртгэлийн дугаар<br><input id="gref" style="width:200px"></label><label>Илгээсэн огноо<br><input id="gat" type="datetime-local" value="${new Date(Date.now() + 8 * 3600e3).toISOString().slice(0, 16)}"></label><button class="primary small" onclick="amlSubmit(${r.id})">Илгээсэн гэж тэмдэглэх</button></div><div style="font-size:11.5px;color:var(--muted);margin-top:6px">Портал ажиллахгүй бол fiu@mongolbank.mn хаягаар нэн даруй мэдэгдэнэ (А-171 4.10). Илгээсэн тайланг засахгүй — шинэ мэдээлэл гарвал нэмэлт тайлан үүсгэнэ (А-171 2.5).</div></div>`}`);
    if (!sub) $('#rf').addEventListener('submit', async (e) => { e.preventDefault(); const fm = e.target; const o = { type: r.type, profile_id: fm.profile_id.value || null, grounds: fm.grounds.value, indicators: [...fm.querySelectorAll('input[name=ind]:checked')].map((x) => x.value), tx_id: r.tx_id, referral_id: r.referral_id }; const x = await api('/aml/reports/' + r.id, { method: 'PUT', body: o }); if (!err(x)) reportView(r.id); });
  }
  window.amlSubmit = async (id) => { const ref = $('#gref').value.trim(); if (!ref) return alert('goAML бүртгэлийн дугаар'); const at = $('#gat').value ? new Date($('#gat').value + ':00+08:00').toISOString() : null; const r = await api(`/aml/reports/${id}/submit`, { method: 'POST', body: { goaml_ref: ref, submitted_at: at } }); if (!err(r)) reportView(id); };

  // ---------------- Сэжиг ----------------
  async function referralForm(pid) {
    const mine = await api('/aml/referrals'); const ps = await api('/aml/profiles');
    body(`<div class="card"><h3>Сэжигтэй үйлдэл мэдээлэх</h3><div style="font-size:12.5px;color:var(--muted);margin-bottom:8px">Комплаенсын ажилтанд нууцаар хүргэгдэнэ. Сэжиг илэрснээс хойш 24 цагийн дотор СМА-д мэдээлэх ёстой тул нэн даруй илгээнэ үү (МУТСТХ 7.2). <b>Харилцагчид мэдэгдэхийг хуулиар хориглоно (13.1).</b></div>
      <form id="rff"><div class="field"><label>Харилцагч</label><select name="profile_id"><option value="">—</option>${ps.map((p) => `<option value="${p.id}" ${pid == p.id ? 'selected' : ''}>${esc(pname(p))}</option>`).join('')}</select></div>
      <div class="field"><label>Шинж тэмдэг</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 12px;font-size:12.5px">${AM.rules.indicators.map((x) => `<label style="display:flex;gap:6px;font-weight:400"><input type="checkbox" name="ind" value="${esc(x)}" style="width:auto"> ${esc(x)}</label>`).join('')}</div></div>
      <div class="field"><label>Юу болсон, яагаад сэжиглэсэн (дэлгэрэнгүй)</label><textarea name="text" rows="4" required minlength="10"></textarea></div><button class="primary small">Илгээх</button></form></div>
    ${!AM.officer && mine.length ? `<div class="card"><h3>Миний илгээсэн</h3>${mine.map((m) => `<div style="font-size:12.5px;border-bottom:1px solid var(--line);padding:4px 0">${dt(m.created_at)} · ${esc(m.text.slice(0, 120))}</div>`).join('')}</div>` : ''}`);
    $('#rff').addEventListener('submit', async (e) => { e.preventDefault(); const f = e.target; const r = await api('/aml/referrals', { method: 'POST', body: { profile_id: f.profile_id.value || null, text: f.text.value, indicators: [...f.querySelectorAll('input[name=ind]:checked')].map((x) => x.value) } }); if (err(r)) return; alert(r.msg); compliance(AM.officer ? 'referrals' : 'referral'); });
  }
  async function referrals() {
    const rows = await api('/aml/referrals');
    body(`<div style="margin-bottom:10px"><button class="small primary" onclick="amlReferral()">+ Сэжиг бүртгэх</button></div><div class="tablebox"><table><thead><tr><th>Огноо</th><th>Илгээсэн</th><th>Тайлбар</th><th>Төлөв</th><th></th></tr></thead><tbody>${rows.map((f) => `<tr><td>${dt(f.created_at)}</td><td>${esc(f.created_by_name || '')}</td><td>${esc(f.text)}${(f.indicators || []).length ? `<div style="font-size:11.5px;color:var(--muted)">${f.indicators.map(esc).join('; ')}</div>` : ''}${f.decision ? `<div style="font-size:12px;margin-top:4px"><b>Шийдвэр:</b> ${esc(f.decision)}</div>` : ''}</td>
      <td>${f.status === 'open' ? b('Шийдээгүй', 'hi') : f.status === 'reported' ? b('СГТ үүсгэсэн', 'ok') : b('Арга хэмжээ шаардлагагүй', 'mut')}</td>
      <td style="white-space:nowrap">${f.status === 'open' ? `<button class="small primary" onclick="amlDecide(${f.id},'str')">СГТ үүсгэх</button> <button class="small" onclick="amlDecide(${f.id},'no')">Үндэслэлгүй</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="5" style="color:var(--muted)">Мэдээлэл алга</td></tr>'}</tbody></table></div>`);
  }
  window.amlDecide = async (id, action) => { const decision = prompt(action === 'str' ? 'СГТ үүсгэх шийдвэрийн үндэслэл:' : 'Сэжиг үндэслэлгүй гэж үзсэн шалтгаан (баримтжуулна):'); if (!decision) return; const r = await api('/aml/referrals/' + id, { method: 'PUT', body: { action, decision } }); if (err(r)) return; if (r.report) compliance('reports', r.report.id); else compliance('referrals'); };

  // ---------------- Хориг жагсаалт ----------------
  async function sanctions() {
    const s = await api('/aml/sanctions'); const st = s.status || {};
    body(`<div class="card"><h3>Жагсаалтын төлөв</h3><div style="font-size:13px;line-height:1.7">НҮБ-ын Аюулгүйн зөвлөлийн нэгдсэн жагсаалт: <b>${st.un ? st.un.n : 0}</b> бичлэг${st.un ? ` · шинэчилсэн ${dt(st.un.at)}` : ''}${st.generated ? ` · НҮБ-ын хувилбар ${esc(st.generated.slice(0, 10))}` : ''} — өдөр бүр автоматаар татна.<br>
      Засгийн газрын дотоодын жагсаалт: <b>${st.mn ? st.mn.n : 0}</b> бичлэг (nctc.gov.mn-ээс платформын эзэн оруулна).${st.lastError ? `<br><b style="color:#dc2626">Сүүлийн алдаа: ${esc(st.lastError.msg)} (${dt(st.lastError.at)})</b>` : ''}</div>
      <div style="font-size:12px;color:var(--muted);margin-top:6px">Шинэ харилцагч, мэдээлэл өөрчлөгдөх, жагсаалт шинэчлэгдэх бүрд бүх профайлыг дахин тулгана (ЗГ-464 6.1; УСҮАЖ 14.2, 14.7). Нэрийг кирилл/латинаар, дарааллаас үл хамааран тулгаж, 90%-иас дээш ижил төстэйг «боломжит тохирол» гэж гаргана.</div>
      ${ME.is_owner ? '<button class="small" style="margin-top:8px" onclick="amlRefreshUN()">НҮБ-ын жагсаалтыг одоо шинэчлэх</button>' : ''}</div>
    <div class="card"><h3>Нэрээр шалгах</h3><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="sn" placeholder="Овог нэр (кирилл эсвэл латин)" style="width:260px"><input id="sd" type="date"><button class="small" onclick="amlTest()">Шалгах</button></div><div id="sr" style="font-size:12.5px;margin-top:8px"></div></div>
    <div class="card"><h3>Дотоодын жагсаалт</h3>${(s.national || []).map((x) => `<div style="font-size:12.5px;border-bottom:1px solid var(--line);padding:4px 0"><b>${esc((x.names || []).join(' / '))}</b> · ${esc(x.ref)} · ${x.kind === 'entity' ? 'хуулийн этгээд' : 'хувь хүн'}${(x.dob || []).length ? ' · ' + esc(x.dob.join(', ')) : ''} ${ME.is_owner ? `<button class="small" onclick="amlNatDel('${esc(x.ref)}')">Хасах</button>` : ''}</div>`).join('') || '<div style="font-size:12.5px;color:var(--muted)">Бичлэг алга</div>'}
      ${ME.is_owner ? `<form id="nf" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><input name="names" placeholder="Нэр; өөр нэр (;-ээр)" style="width:240px" required><input name="ref" placeholder="Дугаар" style="width:100px"><select name="kind" style="width:auto"><option value="individual">Хувь хүн</option><option value="entity">Хуулийн этгээд</option></select><input name="dob" placeholder="Төрсөн огноо/он" style="width:120px"><button class="small primary">Нэмэх</button></form>` : ''}</div>`);
    if (ME.is_owner) $('#nf').addEventListener('submit', async (e) => { e.preventDefault(); const r = await api('/owner/aml/sanctions/national', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) }); if (!err(r)) { alert(`Нэмэгдлээ. ${r.profiles} профайлыг дахин тулгав, шинэ тохирол: ${r.newHits}`); compliance('sanctions'); } });
  }
  window.amlTest = async () => { const r = await api('/aml/sanctions/test', { method: 'POST', body: { name: $('#sn').value, dob: $('#sd').value || null } }); $('#sr').innerHTML = (r.hits || []).length ? r.hits.map((h) => `<div>${b(Math.round(h.score * 100) + '%', h.score > 0.95 ? 'hi' : 'warn')} ${esc(h.name)} · ${esc(h.source)} ${esc(h.ref)}${h.dob === true ? ' · төрсөн огноо таарсан' : ''}</div>`).join('') : '<span style="color:var(--ok)">✓ Тохирол илрээгүй</span>'; };
  window.amlRefreshUN = async () => { const r = await api('/owner/aml/sanctions/refresh', { method: 'POST' }); if (!err(r)) { alert(`${r.n} бичлэг. ${r.profiles} профайл дахин тулгагдав, шинэ тохирол ${r.newHits}.`); compliance('sanctions'); } };
  window.amlNatDel = async (ref) => { if (!confirm('Хасах уу?')) return; await api('/owner/aml/sanctions/national/' + encodeURIComponent(ref), { method: 'DELETE' }); compliance('sanctions'); };

  // ---------------- Ажилтан ----------------
  async function staff() {
    const rows = await api('/aml/staff');
    body(`<div class="card" style="font-size:12.5px;color:var(--muted)">СЗХ-ны №648 журам: 1+ брокер (2+ жилийн туршлагатай), 1+ агент эсвэл борлуулалтын ажилтан, МУТСТ ажилтан; бүгд эрх олгох сургалтын гэрчилгээтэй (2.1.4–2.1.7); тохиромжтой этгээдийн шалгуур (4.1). Брокер, агент, МУТСТ ажилтан өөрчлөгдвөл ажлын 10 өдөрт СЗХ-д мэдэгдэнэ (6.1, 9.2) — «СЗХ» хэсэгт бүртгэнэ.</div>
    <div class="tablebox"><table><thead><tr><th>Ажилтан</th><th>Албан тушаал</th><th>Гэрчилгээ №</th><th>Олгосон</th><th>Хүчинтэй</th><th>Тохиромжтой этгээд шалгасан</th><th></th></tr></thead><tbody>${rows.map((u) => `<tr data-u="${u.user_id}"><td><b>${esc(u.name)}</b></td>
      <td><select data-k="position" style="width:auto">${Object.entries(POS).map(([k, t]) => `<option value="${k}" ${(u.position || (u.role === 'zahiral' ? 'executive' : 'agent')) === k ? 'selected' : ''}>${t}</option>`).join('')}</select></td>
      <td><input data-k="cert_no" value="${esc(u.cert_no || '')}" style="width:110px"></td><td><input data-k="cert_issued" type="date" value="${esc(u.cert_issued || '')}"></td><td><input data-k="cert_expires" type="date" value="${esc(u.cert_expires || '')}"></td><td><input data-k="fit_checked" type="date" value="${esc(u.fit_checked || '')}"></td>
      <td><button class="small" onclick="amlStaff(${u.user_id})">Хадгалах</button></td></tr>`).join('')}</tbody></table></div>
    <div style="font-size:11.5px;color:var(--muted);margin-top:6px">Гэрчилгээний хүчинтэй хугацааг СЗХ-ны журмаас баталгаажуулж чадаагүй (салбарын холбоо 2 жил гэж зарласан) — гэрчилгээн дээрх огноог оруулна уу.</div>`);
  }
  window.amlStaff = async (uid) => { const tr = document.querySelector(`tr[data-u="${uid}"]`); const o = {}; tr.querySelectorAll('[data-k]').forEach((el) => { o[el.dataset.k] = el.value; }); const r = await api('/aml/staff/' + uid, { method: 'PUT', body: o }); if (!err(r)) tr.style.background = 'color-mix(in srgb, var(--ok) 8%, transparent)'; };

  // ---------------- Хөтөлбөр, тохиргоо, сургалт ----------------
  async function program() {
    const s = AM.settings; const tr = await api('/aml/training'); const docs = await api('/aml/docs'); const isZ = ME.role === 'zahiral' || ME.is_owner; const dis = isZ ? '' : 'disabled';
    body(`<form id="pf"><div class="card"><h3>СЗХ-ны зөвшөөрөл</h3><div class="form-grid" style="grid-template-columns:1fr 1fr 1fr">
      <div class="field"><label>Зөвшөөрлийн дугаар</label><input name="lic_no" value="${esc(s.license.no)}" ${dis}></div><div class="field"><label>Олгосон огноо</label><input name="lic_issued" type="date" value="${esc(s.license.issued)}" ${dis}></div><div class="field"><label>Хүчинтэй (хугацаатай бол)</label><input name="lic_expires" type="date" value="${esc(s.license.expires)}" ${dis}></div></div>
      <div style="font-size:11.5px;color:var(--muted)">2026-07-03-ны хуулиар үл хөдлөх хөрөнгийн зуучлал «энгийн зөвшөөрөл»-д шилжсэн (Зөвшөөрөл, мэдэгдлийн тухай хууль 8.2); шилжилтийн журмыг СЗХ-оос тодруулна.</div></div>
    <div class="card"><h3>МУТСТ-ийн хэрэгжилтэд хяналт тавих ажилтан <span style="font-size:12px;color:var(--muted);font-weight:400">СЗХ №648 2.1.5; УСҮАЖ 11.4 — удирдах түвшний, бүх мэдээлэлд нэвтрэх эрхтэй</span></h3>
      <div style="display:flex;gap:12px;flex-wrap:wrap">${AM.users.map((u) => `<label style="display:flex;gap:6px;align-items:center;font-weight:400"><input type="checkbox" name="off" value="${u.id}" ${s.officers.includes(u.id) ? 'checked' : ''} ${dis} style="width:auto"> ${esc(u.name)}</label>`).join('')}</div></div>
    <div class="card"><h3>Дотоод хяналт, эрсдэлийн удирдлагын хөтөлбөр <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 14.1–14.5</span></h3><div class="form-grid" style="grid-template-columns:1fr 1fr">
      <div class="field"><label>Баталсан огноо (ТУЗ / удирдлага)</label><input name="pg_approved" type="date" value="${esc(s.program.approved_at)}" ${dis}></div><div class="field"><label>Шийдвэрийн дугаар</label><input name="pg_decision" value="${esc(s.program.decision)}" ${dis}></div>
      <div class="field"><label>СЗХ-д бүртгүүлсэн огноо (14.5)</label><input name="pg_frc" type="date" value="${esc(s.program.frc_registered_at)}" ${dis}></div><div class="field"><label>СЗХ-ны бүртгэлийн дугаар / албан бичиг</label><input name="pg_ref" value="${esc(s.program.frc_ref)}" ${dis}></div></div>
      <div style="font-size:11.5px;color:var(--muted)">Хөтөлбөрт 14.4.1–14.4.13-т заасан асуудлууд (эрсдэлийн аргачлал, нарийвчилсан ХТМ, хориг арга хэмжээ, тусгай хяналт, СГТ ба нууцлал, ажилтан томилох журам, дотоод сургалт г.м.) тусгагдсан байна.</div></div>
    <div class="card"><h3>Байгууллагын эрсдэлийн үнэлгээ <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 4.3, 4.4</span></h3><div class="form-grid" style="grid-template-columns:200px 1fr"><div class="field"><label>Огноо</label><input name="ra_date" type="date" value="${esc(s.risk_assessment.date)}" ${dis}></div><div class="field"><label>Дүгнэлт</label><textarea name="ra_summary" rows="2" ${dis}>${esc(s.risk_assessment.summary)}</textarea></div></div></div>
    <div class="card"><h3>Аргачлалын тохиргоо</h3><div class="form-grid" style="grid-template-columns:1fr 1fr">
      <div class="field"><label>ФАТФ хар жагсаалт (ISO код, МУТСТХ 5.9.2)</label><input name="fatf_black" value="${esc((s.fatf.black || []).join(', '))}" ${dis}></div><div class="field"><label>ФАТФ саарал жагсаалт</label><input name="fatf_grey" value="${esc((s.fatf.grey || []).join(', '))}" ${dis} placeholder="fatf-gafi.org-оос"></div>
      <div class="field"><label>Жагсаалтыг шинэчилсэн огноо</label><input name="fatf_upd" type="date" value="${esc(s.fatf.updated || '')}" ${dis}></div><div class="field"><label>Дахин шалгах давтамж (сар): өндөр / дунд / бага</label><div style="display:flex;gap:6px"><input name="rv_h" type="number" value="${s.review_months.high}" ${dis}><input name="rv_m" type="number" value="${s.review_months.medium}" ${dis}><input name="rv_l" type="number" value="${s.review_months.low}" ${dis}></div></div>
      <div class="field wide"><label style="display:flex;gap:6px;align-items:center;font-weight:400"><input type="checkbox" name="strict" ${s.strict ? 'checked' : ''} ${dis} style="width:auto"> Хатуу горим: ХТМ баталгаажаагүй гүйлгээг «яаралтай» ажилд оруулна</label></div></div>
      <div style="font-size:11.5px;color:var(--muted)">Эх сурвалж: <a href="${esc(s.fatf.src)}" target="_blank" rel="noopener">ФАТФ-ын хар, саарал жагсаалт</a> — жилд 3 удаа (2, 6, 10-р сард) шинэчлэгддэг.</div></div>
    ${isZ ? '<button class="primary" style="margin-bottom:14px">Хадгалах</button>' : ''}</form>
    <div class="card"><h3>Баримт бичиг (хөтөлбөр, шийдвэр, зөвшөөрөл)</h3>${docs.map((x) => `<div style="font-size:12.5px;border-bottom:1px solid var(--line);padding:4px 0"><a href="#" onclick="amlDoc(${x.id});return false">${esc(AM.rules.doc_kinds[x.kind] || x.kind)}</a> · ${esc(x.orig_name || '')} · ${dt(x.created_at)}</div>`).join('') || '<div style="font-size:12.5px;color:var(--muted)">Баримт алга</div>'}
      <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap"><select id="cdk" style="width:auto">${['program', 'decision', 'license', 'report', 'training', 'other'].map((k) => `<option value="${k}">${esc(AM.rules.doc_kinds[k])}</option>`).join('')}</select><input type="file" id="cdf" accept="application/pdf,image/*" style="width:auto"><button class="small" onclick="amlCoDoc()">Оруулах</button></div></div>
    <div class="card"><h3>Сургалт <span style="font-size:12px;color:var(--muted);font-weight:400">МУТСТХ 14.4 (дотоод сургалтын хөтөлбөр); ЗГ-464 6.1.5 (хориг арга хэмжээ)</span></h3>
      <div class="tablebox"><table><thead><tr><th>Огноо</th><th>Сэдэв</th><th>Төрөл</th><th class="num">Цаг</th><th>Сургагч</th><th>Оролцогч</th></tr></thead><tbody>${tr.map((t) => `<tr><td>${esc(t.date)}</td><td>${esc(t.topic)}</td><td>${{ internal: 'Дотоод', certificate: 'Гэрчилгээний', sanctions: 'Хориг арга хэмжээ' }[t.kind] || ''}</td><td class="num">${t.hours}</td><td>${esc(t.trainer || '')}</td><td>${(t.attendees || []).map((id) => esc((AM.users.find((u) => u.id === id) || {}).name || '#' + id)).join(', ')}</td></tr>`).join('') || '<tr><td colspan="6" style="color:var(--muted)">Сургалт бүртгэгдээгүй</td></tr>'}</tbody></table></div>
      <form id="tf" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;align-items:flex-end"><input name="date" type="date" required><input name="topic" placeholder="Сэдэв" required style="width:220px"><select name="kind" style="width:auto"><option value="internal">Дотоод</option><option value="sanctions">Хориг арга хэмжээ</option><option value="certificate">Гэрчилгээний</option></select><input name="hours" type="number" step="0.5" placeholder="Цаг" style="width:70px"><input name="trainer" placeholder="Сургагч" style="width:140px">
        <select name="att" multiple size="3" style="width:180px">${AM.users.map((u) => `<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select><button class="small primary">Нэмэх</button></form></div>`);
    if (isZ) $('#pf').addEventListener('submit', async (e) => {
      e.preventDefault(); const f = e.target;
      const o = { license: { no: f.lic_no.value, issued: f.lic_issued.value, expires: f.lic_expires.value }, officers: [...f.querySelectorAll('input[name=off]:checked')].map((x) => Number(x.value)), program: { approved_at: f.pg_approved.value, decision: f.pg_decision.value, frc_registered_at: f.pg_frc.value, frc_ref: f.pg_ref.value }, risk_assessment: { date: f.ra_date.value, summary: f.ra_summary.value }, fatf: { black: f.fatf_black.value, grey: f.fatf_grey.value, updated: f.fatf_upd.value }, review_months: { high: f.rv_h.value, medium: f.rv_m.value, low: f.rv_l.value }, strict: f.strict.checked };
      const r = await api('/aml/settings', { method: 'PUT', body: o }); if (!err(r)) compliance('program');
    });
    $('#tf').addEventListener('submit', async (e) => { e.preventDefault(); const f = e.target; const o = Object.fromEntries(new FormData(f)); o.attendees = [...f.att.selectedOptions].map((x) => Number(x.value)); delete o.att; const r = await api('/aml/training', { method: 'POST', body: o }); if (!err(r)) compliance('program'); });
  }
  window.amlCoDoc = async () => { const f = $('#cdf').files[0]; if (!f) return alert('Файл сонгоно уу'); const fd = new FormData(); fd.append('file', f); fd.append('kind', $('#cdk').value); fd.append('owner_type', 'company'); const r = await upload('/aml/docs', fd); if (!err(r)) compliance('program'); };

  // ---------------- СЗХ: тайлангийн хуваарь, өөрчлөлтийн мэдэгдэл, улирлын нэгтгэл ----------------
  async function frc() {
    const ch = await api('/aml/changes'); const filed = new Map((AM.filings || []).map((f) => [f.key + '|' + f.period, f])); const today = new Date(Date.now() + 8 * 3600e3).toISOString().slice(0, 10);
    const q = (() => { const d = new Date(Date.now() + 8 * 3600e3); let y = d.getUTCFullYear(), qq = Math.floor(d.getUTCMonth() / 3); if (qq === 0) { y--; qq = 4; } return `${y}-Q${qq}`; })();
    body(`<div class="card"><h3>Тайлангийн хуваарь</h3><div class="tablebox"><table><thead><tr><th>Тайлан</th><th>Хугацаа</th><th>Эх сурвалж</th><th>Төлөв</th></tr></thead><tbody>${AM.calendar.map((c) => { const f = filed.get(c.key + '|' + c.period); const late = !f && c.due < today; return `<tr><td>${esc(c.t)} — <b>${esc(c.period)}</b>${c.soft ? ' <span style="font-size:11px;color:var(--muted)">(хугацааг журамд заагаагүй)</span>' : ''}</td><td>${esc(c.due)}</td><td style="font-size:12px">${esc(c.cite)}</td><td>${f ? b('Илгээсэн ' + esc(f.submitted_at ? String(f.submitted_at).slice(0, 10) : ''), 'ok') : `${late ? b('ХЭТЭРСЭН', 'hi') : ''} <button class="small" onclick="amlFiled('${c.key}','${c.period}')">Илгээсэн гэж тэмдэглэх</button>`}</td></tr>`; }).join('')}</tbody></table></div>
      <div style="font-size:11.5px;color:var(--muted);margin-top:6px">Улирлын 11 маягтыг СЗХ-ны цахим тайлангийн системээр, frc.mn-ээс тухай бүр татсан Excel загвараар илгээнэ (№235 5.1; 2026 оны №108-аар зөвхөн цахимаар). Тайлан хугацаандаа ирүүлээгүй бол зөвшөөрлийг 3 сар хүртэл түдгэлзүүлж болно (Зөвшөөрөл, мэдэгдлийн тухай хууль 6.1.1.2).</div></div>
    <div class="card"><h3>Улирлын маягт 6, 7-д ашиглах нэгтгэл</h3><div style="display:flex;gap:8px;align-items:center"><input id="qp" value="${q}" style="width:110px"><button class="small" onclick="amlQuarter()">Тооцох</button></div><div id="qr" style="font-size:12.5px;margin-top:8px"></div></div>
    <div class="card"><h3>СЗХ-д урьдчилан мэдэгдэх өөрчлөлт <span style="font-size:12px;color:var(--muted);font-weight:400">№648 6.1 — шийдвэр гарснаас хойш ажлын 10 өдөрт (9.2)</span></h3>
      <div class="tablebox"><table><thead><tr><th>Төрөл</th><th>Тайлбар</th><th>Шийдвэр</th><th>Эцсийн хугацаа</th><th>Төлөв</th></tr></thead><tbody>${ch.map((c) => `<tr><td>${esc(AM.rules.change_types[c.type] || c.type)}</td><td>${esc(c.description || '')}</td><td>${esc(c.decision_date)}</td><td>${!c.submitted_at && c.due < today ? b(esc(c.due) + ' ХЭТЭРСЭН', 'hi') : esc(c.due)}</td><td>${c.submitted_at ? b('Мэдэгдсэн ' + esc(c.submitted_at) + (c.frc_ref ? ' · ' + esc(c.frc_ref) : ''), 'ok') : `<button class="small" onclick="amlChangeDone(${c.id})">Мэдэгдсэн</button>`}</td></tr>`).join('') || '<tr><td colspan="5" style="color:var(--muted)">Бүртгэл алга</td></tr>'}</tbody></table></div>
      <form id="cf" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><select name="type" style="width:auto">${Object.entries(AM.rules.change_types).map(([k, t]) => `<option value="${k}">${esc(t)}</option>`).join('')}</select><input name="decision_date" type="date" required><input name="description" placeholder="Тайлбар (жишээ: брокер Б.Болд томилогдсон)" style="width:260px"><button class="small primary">Бүртгэх</button></form></div>
    <div class="card"><h3>Шалгалтад бэлэн байдал <span style="font-size:12px;color:var(--muted);font-weight:400">СЗХ №22, 7.1 — шалгалтад гаргуулах баримт</span></h3>
      <ul style="font-size:12.5px;line-height:1.7;padding-left:18px;margin:0">${[['Улсын бүртгэл, зөвшөөрөл', !!AM.settings.license.no], ['МУТСТ ажилтныг томилсон шийдвэр', AM.settings.officers.length > 0], ['МУТСТ дотоод хөтөлбөр, баталсан шийдвэр', !!AM.settings.program.approved_at], ['Хөтөлбөрийг СЗХ-д бүртгүүлсэн', !!AM.settings.program.frc_registered_at], ['Эрсдэлийн үнэлгээ', !!AM.settings.risk_assessment.date], ['ХТМ-ийн баримт (бүртгэл)', AM.stats.profiles.length > 0], ['СМА-нд илгээсэн мэдээлэл (goAML бүртгэл)', true], ['Хориг арга хэмжээний хэрэгжилт (жагсаалт, тулгалт)', !!(AM.sanctions && AM.sanctions.un)], ['Дотоод сургалтын бүртгэл', !AM.tasks.some((t) => /сургалт/.test(t.t))]].map(([t, ok]) => `<li>${ok ? '✅' : '⬜'} ${esc(t)}</li>`).join('')}</ul>
      <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="small primary" onclick="amlExport()">Шалгалтын багц татах (JSON)</button><button class="small" onclick="compliance('audit')">Аудитын бүртгэл</button></div></div>`);
    $('#cf').addEventListener('submit', async (e) => { e.preventDefault(); const r = await api('/aml/changes', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) }); if (!err(r)) { alert('Эцсийн хугацаа: ' + r.due); compliance('frc'); } });
  }
  window.amlFiled = async (key, period) => { const ref = prompt('Илгээсэн тэмдэглэл (бүртгэлийн дугаар, огноо):', ''); if (ref === null) return; const r = await api('/aml/filings', { method: 'POST', body: { key, period, ref } }); if (!err(r)) compliance('frc'); };
  window.amlChangeDone = async (id) => { const ref = prompt('СЗХ-д мэдэгдсэн албан бичгийн дугаар:', ''); if (ref === null) return; const r = await api('/aml/changes/' + id, { method: 'PUT', body: { frc_ref: ref } }); if (!err(r)) compliance('frc'); };
  window.amlQuarter = async () => { const r = await api('/aml/quarter?period=' + encodeURIComponent($('#qp').value)); if (err(r)) return; const T = { sale: 'Худалдах, худалдан авах (маягт 6)', rent: 'Түрээс (маягт 7)' }; const P = { transfer: 'шилжүүлэг', mortgage: 'ипотек', cash: 'бэлэн' };
    $('#qr').innerHTML = `<div style="color:var(--muted)">${esc(r.from)} — ${esc(r.to)} (хамаарахгүй)</div><table style="margin-top:4px"><thead><tr><th>Төрөл</th><th>Төлбөр</th><th class="num">Тоо</th><th class="num">Дүн, сая ₮</th><th class="num">Шимтгэл, сая ₮</th></tr></thead><tbody>${r.rows.map((x) => `<tr><td>${T[x.deal_type] || esc(x.deal_type)}</td><td>${P[x.payment_form] || esc(x.payment_form || '')}</td><td class="num">${x.n}</td><td class="num">${x.amount.toFixed(1)}</td><td class="num">${x.commission.toFixed(2)}</td></tr>`).join('') || '<tr><td colspan="5">Хэлцэл алга</td></tr>'}</tbody></table><div style="margin-top:4px">БМГТ: ${r.ctr} · ${esc(r.note)}</div>`; };
  window.amlExport = async () => { const r = await fetch('/api/aml/export', { headers: { Authorization: 'Bearer ' + TOKEN } }); if (!r.ok) return alert((await r.json()).error); const u = URL.createObjectURL(await r.blob()); const a = document.createElement('a'); a.href = u; a.download = `zuuch-komplaens-${new Date().toISOString().slice(0, 10)}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(u), 30000); };

  // ---------------- Аудит ----------------
  async function audit() {
    const rows = await api('/aml/audit');
    body(`<div style="font-size:12.5px;color:var(--muted);margin-bottom:8px">Комплаенсын бүх үйлдэл (үзсэн, засварласан, баримт нээсэн, шийдвэр) өөрчлөх боломжгүйгээр бүртгэгдэнэ — сүүлийн 1000.</div><div class="tablebox"><table><thead><tr><th>Огноо</th><th>Хэрэглэгч</th><th>Үйлдэл</th><th>Объект</th><th>Дэлгэрэнгүй</th></tr></thead><tbody>${rows.map((a) => `<tr><td>${dt(a.created_at)}</td><td>${esc(a.user_name || '')}</td><td>${esc(a.action)}</td><td>${esc(a.entity || '')} ${a.entity_id || ''}</td><td style="font-size:11.5px;color:var(--muted)">${esc(JSON.stringify(a.detail || {})).slice(0, 160)}</td></tr>`).join('')}</tbody></table></div>`);
  }
})();
